// intent: Exercises diff_object_keys fast path, target_values vector, added vector, and subsequent diff additions when keys are reordered and new keys are added.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    nlohmann::ordered_json source = {{"a", 1}, {"b", 2}, {"c", 3}};
    nlohmann::ordered_json target = {{"b", 2}, {"z", 99}, {"a", 1}, {"c", 3}, {"d", 100}};
    auto patch = nlohmann::ordered_json::diff(source, target);
    std::cout << patch.dump(2) << std::endl;
    return 0;
}
